'use client';

import * as React from 'react';

// @interlace/reminder-offer v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/reminder-offer
// What changed since: https://ds.interlace.tools/c/reminder-offer#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — ReminderOffer
 *
 * A quiet offer of a daily nudge that the player keeps in their own
 * calendar: pick a time, add it, done. It downloads an .ics file with one
 * event that repeats daily (`reminder-model.ts`), so nothing is sent, no
 * address is asked for, and the player removes it from their calendar
 * whenever they like. "Not now" dismisses it; the app decides whether it
 * ever comes back.
 *
 * ## Anatomy
 *
 *   ReminderOffer                  (section — data-slot="reminder-offer", data-state=offer|added)
 *     ├─ h3                        (data-slot="reminder-offer-title")
 *     ├─ p                         (data-slot="reminder-offer-body")
 *     ├─ div                       (data-slot="reminder-offer-controls")
 *     │   ├─ label + input[time]   (data-slot="reminder-offer-time")
 *     │   ├─ button                (data-slot="reminder-offer-add")
 *     │   └─ button                (data-slot="reminder-offer-dismiss", with onDismiss)
 *     └─ p aria-live="polite"      (data-slot="reminder-offer-status")
 *
 * ## Gentle by design
 *
 * One offer, two plain choices, no badge, no countdown, no guilt. It does
 * not ask the browser for notification permission.
 *
 * ## MIN_VIEWPORT — 320
 *
 * Controls stack below a 24rem container.
 *
 * | Rule | Concept                   | Where in this file                                 |
 * | ---- | ------------------------- | -------------------------------------------------- |
 * | R4   | Extends native el         | `React.ComponentProps<'section'>`                  |
 * | R6   | data-slot per part        | reminder-offer / -title / -body / -controls / -time / -add / -dismiss / -status |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                  |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const               |
 * | R19  | Tokens only               | card, border, muted-foreground, input              |
 * | R25  | Client component          | builds and downloads the file                      |
 * | R26  | A11y                      | labelled time field; live status                   |
 */

import { BellRing } from 'lucide-react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { dayKey } from '@/components/ui/games/daily';
import { isReminderTime, reminderIcs } from '@/components/ui/games/reminder-model';

export const MIN_VIEWPORT = 320 as const;

interface ReminderOfferLabels {
  /** @default 'A nudge each day?' */
  title?: string;
  /** @default 'Add a daily reminder to your own calendar. Nothing is sent to us, and you can remove it there any time.' */
  body?: string;
  /** @default 'Time' */
  time?: string;
  /** @default 'Add to my calendar' */
  add?: string;
  /** @default 'Not now' */
  dismiss?: string;
  /** @default 'Added. Open the file to save it in your calendar.' */
  added?: string;
}

type ReminderOfferProps = Omit<React.ComponentProps<'section'>, 'title'> & {
  /** The calendar event's title. */
  event: string;
  /** A line under the event's title. */
  eventDescription?: string;
  /** Opens from the event. */
  url?: string;
  /** Stable id, so adding again updates the same event. */
  uid: string;
  /** "HH:MM". @default '18:30' */
  defaultTime?: string;
  /** @default 'reminder.ics' */
  fileName?: string;
  /** Called with the time after the file is made. */
  onAdd?: (time: string) => void;
  /** Shows "Not now" and is called when pressed. */
  onDismiss?: () => void;
  labels?: ReminderOfferLabels;
};

function ReminderOffer({
  event,
  eventDescription,
  url,
  uid,
  defaultTime = '18:30',
  fileName = 'reminder.ics',
  onAdd,
  onDismiss,
  labels,
  className,
  ...props
}: ReminderOfferProps) {
  const id = React.useId();
  const [time, setTime] = React.useState(isReminderTime(defaultTime) ? defaultTime : '18:30');
  const [added, setAdded] = React.useState(false);

  const add = () => {
    const chosen = isReminderTime(time) ? time : '18:30';
    const ics = reminderIcs({ title: event, description: eventDescription, url, uid, time: chosen, start: dayKey() });
    const href = URL.createObjectURL(new Blob([ics], { type: 'text/calendar;charset=utf-8' }));
    const a = document.createElement('a');
    a.href = href;
    a.download = fileName;
    document.body.append(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(href), 1000);
    setAdded(true);
    onAdd?.(chosen);
  };

  return (
    <section
      aria-labelledby={`${id}-title`}
      data-slot="reminder-offer"
      data-state={added ? 'added' : 'offer'}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn(
        '@container border-border bg-card text-card-foreground grid gap-3 rounded-xl border p-5',
        className,
      )}
      {...props}
    >
      <div className="flex items-start gap-3">
        <BellRing aria-hidden className="text-primary mt-0.5 size-5 shrink-0" />
        <div className="grid gap-1">
          <h3 id={`${id}-title`} data-slot="reminder-offer-title" className="font-heading font-semibold">
            {labels?.title ?? 'A nudge each day?'}
          </h3>
          <p data-slot="reminder-offer-body" className="text-muted-foreground text-sm text-pretty">
            {labels?.body ??
              'Add a daily reminder to your own calendar. Nothing is sent to us, and you can remove it there any time.'}
          </p>
        </div>
      </div>
      {added ? null : (
        <div data-slot="reminder-offer-controls" className="grid gap-2 @sm:flex @sm:flex-wrap @sm:items-end">
          <label className="grid gap-1 text-sm font-medium" htmlFor={`${id}-time`}>
            {labels?.time ?? 'Time'}
            <input
              id={`${id}-time`}
              type="time"
              data-slot="reminder-offer-time"
              value={time}
              onChange={(e) => setTime(e.target.value)}
              className="border-input bg-background focus-visible:outline-ring h-10 rounded-md border px-3 tabular-nums focus-visible:outline-2 focus-visible:outline-offset-2"
            />
          </label>
          <Button type="button" data-slot="reminder-offer-add" onClick={add}>
            {labels?.add ?? 'Add to my calendar'}
          </Button>
          {onDismiss ? (
            <Button type="button" variant="ghost" data-slot="reminder-offer-dismiss" onClick={onDismiss}>
              {labels?.dismiss ?? 'Not now'}
            </Button>
          ) : null}
        </div>
      )}
      <p data-slot="reminder-offer-status" aria-live="polite" className="text-sm font-medium empty:hidden">
        {added ? (labels?.added ?? 'Added. Open the file to save it in your calendar.') : ''}
      </p>
    </section>
  );
}
ReminderOffer.displayName = 'ReminderOffer';

export { ReminderOffer };
export type { ReminderOfferProps, ReminderOfferLabels };

export type DayKey = string;

const DAY_MS = 86_400_000;
const KEY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * The calendar day `date` falls on in `timeZone` (an IANA name such as
 * `"Europe/Paris"`). Without a time zone, the runtime's own is used, which on
 * a server is usually UTC: pass the player's zone when the page renders on
 * one.
 */
export function dayKey(date: Date | number = Date.now(), timeZone?: string): DayKey {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(typeof date === 'number' ? new Date(date) : date);
  const part = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return `${part.year}-${part.month}-${part.day}`;
}

/** True when `value` is a well-formed day key for a real date. */
export function isDayKey(value: unknown): value is DayKey {
  if (typeof value !== 'string') return false;
  const m = KEY_RE.exec(value);
  if (!m) return false;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return d.getUTCFullYear() === +m[1] && d.getUTCMonth() === +m[2] - 1 && d.getUTCDate() === +m[3];
}

function toUtc(key: DayKey): number {
  const m = KEY_RE.exec(key);
  if (!m) throw new RangeError(`Not a day key: "${key}" (expected YYYY-MM-DD)`);
  return Date.UTC(+m[1], +m[2] - 1, +m[3]);
}

/** Midnight UTC of the day, as a Date: the safe way to format a key with Intl. */
export function dayKeyToDate(key: DayKey): Date {
  return new Date(toUtc(key));
}

/** The key `days` after `key` (negative goes back). */
export function addDays(key: DayKey, days: number): DayKey {
  return new Date(toUtc(key) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Whole days from `from` to `to`; negative when `to` is earlier. */
export function daysBetween(from: DayKey, to: DayKey): number {
  return Math.round((toUtc(to) - toUtc(from)) / DAY_MS);
}

/** Day of the week, 0 for Sunday to 6 for Saturday, as `Date.getDay` counts. */
export function weekdayOf(key: DayKey): number {
  return new Date(toUtc(key)).getUTCDay();
}

/**
 * The puzzle's number: 1 on `firstDay`, 2 the day after. Before `firstDay`
 * it is 0 or less, which a caller should treat as "not started".
 */
export function puzzleNumber(key: DayKey, firstDay: DayKey): number {
  return daysBetween(firstDay, key) + 1;
}

/** FNV-1a, 32-bit: a small, stable string hash for seeds. */
export function hashString(value: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/**
 * A seeded generator of numbers in [0, 1) (mulberry32). Good enough to deal
 * puzzles and shuffle answers the same way everywhere; not for anything
 * secret.
 */
export function seededRandom(seed: number | string): () => number {
  let a = typeof seed === 'string' ? hashString(seed) : seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296;
  };
}

/** A copy of `items` in a seeded order (Fisher–Yates). */
export function seededShuffle<T>(items: readonly T[], seed: number | string): T[] {
  const out = items.slice();
  const random = seededRandom(seed);
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j] as T, out[i] as T];
  }
  return out;
}

export interface DailyIndexOptions {
  /** The day puzzle 1 ran. */
  firstDay: DayKey;
  /** `sequence` walks the pool in order; `shuffle` deals it in a seeded order per cycle. @default 'sequence' */
  order?: 'sequence' | 'shuffle';
  /** Changes the shuffled order. @default 'daily' */
  seed?: string;
}

/**
 * Which item of a pool of `size` the day gets, or -1 for an empty pool or a
 * day before `firstDay`.
 */
export function dailyIndex(key: DayKey, size: number, options: DailyIndexOptions): number {
  const n = puzzleNumber(key, options.firstDay);
  if (size <= 0 || n < 1) return -1;
  const position = (n - 1) % size;
  if ((options.order ?? 'sequence') === 'sequence') return position;
  const cycle = Math.floor((n - 1) / size);
  const order = seededShuffle(
    Array.from({ length: size }, (_, i) => i),
    `${options.seed ?? 'daily'}:${cycle}`,
  );
  return order[position] as number;
}

/** The day's item from `pool`, or undefined when there is none. */
export function dailyItem<T>(pool: readonly T[], key: DayKey, options: DailyIndexOptions): T | undefined {
  const i = dailyIndex(key, pool.length, options);
  return i < 0 ? undefined : pool[i];
}

/**
 * Milliseconds until the next day starts in `timeZone`. On a day that a
 * clock change makes 23 or 25 hours long the answer can be off by that hour,
 * which is fine for a countdown and is why it is not used to pick puzzles.
 */
export function msUntilNextDay(now: Date | number = Date.now(), timeZone?: string): number {
  const date = typeof now === 'number' ? new Date(now) : now;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);
  const part = Object.fromEntries(parts.map((p) => [p.type, Number(p.value)]));
  const elapsed =
    ((part.hour! * 60 + part.minute!) * 60 + part.second!) * 1000 + date.getMilliseconds();
  return DAY_MS - elapsed;
}

/**
 * @interlace/ui — games/daily
 *
 * The calendar under a daily game: which day it is for a player, which
 * puzzle that day gets, its number, and how long until the next one. Pure
 * functions, no React, no storage. Every component in `games/` builds on
 * these, and a server can call them too, so the puzzle a page renders and
 * the one a score is checked against come from the same arithmetic.
 *
 * ## Day keys
 *
 * A day is an ISO date string, `"2026-11-24"`, read in a time zone. Keys
 * sort as strings, survive JSON and storage unchanged, and compare without
 * a Date. Arithmetic on them runs in UTC, where every day has 24 hours, so
 * daylight-saving changes never skip or repeat a day.
 *
 * ## The puzzle of the day
 *
 * `dailyIndex` maps a day to an item in a pool. `order: 'sequence'` walks
 * the pool in order and starts again at the end. `order: 'shuffle'` deals
 * the pool in a seeded order that changes every cycle, and never repeats an
 * item inside a cycle. Both are deterministic: the same day, pool size and
 * seed give the same item on every device.
 */

/** An ISO calendar date, `YYYY-MM-DD`. */

import { isDayKey, type DayKey } from '@/components/ui/games/daily';

/**
 * @interlace/ui — games/reminder-model
 *
 * A daily reminder the player keeps in their own calendar: an iCalendar
 * (.ics) file with one event that repeats every day at a time they chose,
 * with an alert. Nothing is sent and nothing is stored on a server; the
 * player's calendar does the reminding, and they remove it there.
 *
 * Pure, so a server can serve the same file from a link.
 *
 * ## Local time
 *
 * The event uses floating time (no time zone), so "6:30 PM" stays 6:30 PM
 * wherever the player is, which is what a daily habit wants.
 *
 * ## Format
 *
 * RFC 5545: CRLF line ends, text escaped, lines folded at 75 octets.
 */

export interface ReminderInput {
  /** The event's title, as the calendar shows it. */
  title: string;
  /** A line or two under the title. */
  description?: string;
  /** Opens from the event. */
  url?: string;
  /** "HH:MM", 24-hour, the player's local time. */
  time: string;
  /** The first day. */
  start: DayKey;
  /** Minutes the event lasts. @default 10 */
  minutes?: number;
  /** Stable id, so adding it again updates rather than duplicates. */
  uid: string;
  /** Names the app that made the file. @default '-//Interlace//Reminder//EN' */
  prodId?: string;
  /** When the file was made, for DTSTAMP. @default now */
  now?: Date;
}

const TIME = /^([01]\d|2[0-3]):([0-5]\d)$/;

/** True for a 24-hour "HH:MM". */
export function isReminderTime(value: string): boolean {
  return TIME.test(value);
}

/** Escapes text for an iCalendar value. */
export function escapeIcsText(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
}

/** Folds a content line at 75 octets, continuation lines starting with a space. */
export function foldIcsLine(line: string): string {
  const enc = new TextEncoder();
  const parts: string[] = [];
  let current = '';
  let size = 0;
  for (const ch of line) {
    const n = enc.encode(ch).length;
    const limit = parts.length === 0 ? 75 : 74;
    if (size + n > limit) {
      parts.push(current);
      current = '';
      size = 0;
    }
    current += ch;
    size += n;
  }
  parts.push(current);
  return parts.join('\r\n ');
}

const pad = (n: number) => String(n).padStart(2, '0');

function stampUtc(d: Date): string {
  return `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}T${pad(d.getUTCHours())}${pad(
    d.getUTCMinutes(),
  )}${pad(d.getUTCSeconds())}Z`;
}

/** The .ics text for a daily reminder. Throws on a bad time or day key. */
export function reminderIcs(input: ReminderInput): string {
  const match = TIME.exec(input.time);
  if (!match) throw new RangeError(`reminderIcs: time must be "HH:MM", got "${input.time}"`);
  if (!isDayKey(input.start)) throw new RangeError(`reminderIcs: start must be a day key, got "${input.start}"`);
  const hour = Number(match[1]);
  const minute = Number(match[2]);
  const length = Math.max(1, Math.min(120, Math.floor(input.minutes ?? 10)));
  const date = input.start.replace(/-/g, '');
  const endMinutes = hour * 60 + minute + length;
  // An event that would end after midnight ends at 23:59 instead.
  const end = endMinutes >= 24 * 60 ? '235900' : `${pad(Math.floor(endMinutes / 60))}${pad(endMinutes % 60)}00`;
  const lines = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    `PRODID:${input.prodId ?? '-//Interlace//Reminder//EN'}`,
    'CALSCALE:GREGORIAN',
    'BEGIN:VEVENT',
    `UID:${input.uid}`,
    `DTSTAMP:${stampUtc(input.now ?? new Date())}`,
    `DTSTART:${date}T${pad(hour)}${pad(minute)}00`,
    `DTEND:${date}T${end}`,
    'RRULE:FREQ=DAILY',
    `SUMMARY:${escapeIcsText(input.title)}`,
  ];
  if (input.description) lines.push(`DESCRIPTION:${escapeIcsText(input.description)}`);
  if (input.url) lines.push(`URL:${input.url}`);
  lines.push(
    'TRANSP:TRANSPARENT',
    'BEGIN:VALARM',
    'ACTION:DISPLAY',
    `DESCRIPTION:${escapeIcsText(input.title)}`,
    'TRIGGER:PT0M',
    'END:VALARM',
    'END:VEVENT',
    'END:VCALENDAR',
  );
  return lines.map(foldIcsLine).join('\r\n') + '\r\n';
}
